import{_ as t,o as i,c as s,a3 as a}from"./chunks/framework.M8WpjUcN.js";const k=JSON.parse('{"title":"Config port","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config-port.md","filePath":"reference/config-port.md"}'),o={name:"reference/config-port.md"};function d(r,e,c,l,n,h){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="config-port" tabindex="-1">Config port <a class="header-anchor" href="#config-port" aria-label="Permalink to &quot;Config port&quot;">​</a></h1><p>The config plane is two traits plus a search spec, generic over the config model <code>T</code> (<code>Deserialize + Serialize</code>). Scarab never names a consumer&#39;s <code>Config</code> type.</p><h2 id="configformat-t" tabindex="-1"><code>ConfigFormat&lt;T&gt;</code> <a class="header-anchor" href="#configformat-t" aria-label="Permalink to &quot;`ConfigFormat&lt;T&gt;`&quot;">​</a></h2><p>Syntax-level: which extensions a format claims, <code>parse</code>/<code>render</code> over serde. Object-safe via a blanket impl — one <code>TomlFormat</code> / <code>YamlFormat</code> value serves every model.</p><div class="language-rust vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rust</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">pub</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> trait</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> ConfigFormat</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Send</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> +</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Sync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> extensions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">static</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">static</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> parse</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, text</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">str</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    fn</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> render</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">self</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, config</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &amp;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Result</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;;</span></span>\n<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Impl</th><th>Crate</th><th>Claims</th></tr></thead><tbody><tr><td><code>YamlFormat</code></td><td><code>scarab-config-yaml</code></td><td><code>yaml</code>, <code>yml</code> (in that order)</td></tr><tr><td><code>TomlFormat</code></td><td><code>scarab-config-toml</code></td><td><code>toml</code></td></tr></tbody></table><p><code>scarab_config::format_for(path, formats)</code> returns the format claiming <code>path</code>&#39;s extension, or <code>None</code>.</p><h2 id="configsource-t" tabindex="-1"><code>ConfigSource&lt;T&gt;</code> <a class="header-anchor" href="#configsource-t" aria-label="Permalink to &quot;`ConfigSource&lt;T&gt;`&quot;">​</a></h2><p>Source-level: <code>load() -&gt; Result&lt;T, String&gt;</code>. Impls compose formats — <code>scarab-config-file</code>&#39;s <code>FileSource</code> (first-match) and <code>LayeredFileSource</code> (merge-all) are the file-backed impls; env/remote sources are new impls of the same trait.</p><h2 id="discovery" tabindex="-1"><code>Discovery</code> <a class="header-anchor" href="#discovery" aria-label="Permalink to &quot;`Discovery`&quot;">​</a></h2><p>The shared search spec every file-backed source uses. Nothing is hardcoded per app — basename, env var, and dirs are caller-supplied.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>name</code></td><td>Config file basename — <code>myco</code> → <code>myco.yaml</code>, <code>myco.yml</code>, <code>myco.toml</code></td></tr><tr><td><code>env_var</code></td><td>Env var naming an explicit config file (<code>$MYCO_CONFIG</code>); <code>None</code> disables the env step</td></tr><tr><td><code>dirs</code></td><td>Directories searched in order for <code>&lt;name&gt;.&lt;ext&gt;</code>; <code>~</code> expands via <code>expand_tilde</code></td></tr></tbody></table><p>Constructors and builders:</p><ul><li><code>Discovery::for_app(name)</code> — env var <code>&lt;NAME&gt;_CONFIG</code> (uppercased), dirs <code>[&quot;.&quot;, &quot;~/.config/&lt;name&gt;&quot;]</code></li><li><code>Discovery::bare(name)</code> — no env var, no dirs</li><li><code>.env_var(var)</code> / <code>.without_env()</code> — set or disable the env step</li><li><code>.dirs(iter)</code> — replace search dirs, in order</li></ul><h2 id="filesource-t" tabindex="-1"><code>FileSource&lt;T&gt;</code> <a class="header-anchor" href="#filesource-t" aria-label="Permalink to &quot;`FileSource&lt;T&gt;`&quot;">​</a></h2><p>File-backed <code>ConfigSource</code>: discovery + extension dispatch over a set of <code>ConfigFormat&lt;T&gt;</code>s.</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>discovery</code></td><td>Where to search</td></tr><tr><td><code>explicit</code></td><td>Explicit <code>--config</code>-style path; wins over <code>discovery.env_var</code></td></tr><tr><td><code>formats</code></td><td>Syntax formats in preference order</td></tr></tbody></table><p>Constructors:</p><ul><li><code>FileSource::new(discovery)</code> — standard formats <code>[Yaml, Toml]</code></li><li><code>FileSource::with_formats(discovery, formats)</code> — caller-chosen set/order</li><li><code>FileSource::for_app(name)</code> — <code>Discovery::for_app</code> + standard formats</li><li><code>FileSource::standard_formats()</code> — the <code>[YamlFormat, TomlFormat]</code> pair</li></ul><p>Requires <code>T: DeserializeOwned + Serialize</code> for <code>new</code>/<code>for_app</code> (the <code>ConfigSource</code> impl bound).</p><h2 id="layeredfilesource-t" tabindex="-1"><code>LayeredFileSource&lt;T&gt;</code> <a class="header-anchor" href="#layeredfilesource-t" aria-label="Permalink to &quot;`LayeredFileSource&lt;T&gt;`&quot;">​</a></h2><p>The merge counterpart, in <code>scarab-config-file</code>. Where <code>FileSource</code> picks the <em>first</em> existing file, <code>LayeredFileSource</code> collects <strong>one file per search dir</strong> (same per-dir preference rules), folds them low→high precedence into a <code>serde_json::Value</code> tree, applies programmatic dotted-path overrides, then deserializes into <code>T</code>. Formats are held as <code>ConfigFormat&lt;serde_json::Value&gt;</code> — layers merge as JSON, so <code>T</code> only needs <code>DeserializeOwned</code> (no <code>Serialize</code>).</p><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>discovery</code></td><td>Where to search — same <code>Discovery</code> spec</td></tr><tr><td><code>explicit</code></td><td>Explicit path — the <strong>top file layer</strong>, merged over all dir layers (unlike <code>FileSource</code>, where it replaces discovery)</td></tr><tr><td><code>formats</code></td><td>Syntax formats over <code>serde_json::Value</code>, in preference order</td></tr><tr><td><code>overrides</code></td><td><code>BTreeMap&lt;String, Value&gt;</code> — flat dotted-path keys (<code>&quot;server.port&quot;</code>), the highest layer</td></tr></tbody></table><p>Constructors mirror <code>FileSource</code>: <code>new(discovery)</code>, <code>for_app(name)</code>, <code>with_formats(discovery, formats)</code>, <code>standard_formats()</code>.</p><p>Precedence, lowest to highest:</p><ol><li><code>&lt;dir&gt;/&lt;name&gt;.&lt;ext&gt;</code> per dir, <strong>last dir first</strong> — under <code>Discovery::for_app</code> (<code>[&quot;.&quot;, &quot;~/.config/&lt;name&gt;&quot;]</code>) the user config is the base and <code>./&lt;name&gt;.yaml</code> overrides it</li><li>the explicit path / <code>$&lt;NAME&gt;_CONFIG</code> file</li><li><code>overrides</code> — dotted-path leaf values</li></ol><p>Methods: <code>layer_paths()</code> / <code>layer_paths_with(env)</code> (merge order, lowest first), <code>parse_layer(path)</code> (one file → <code>Value</code>; a non-mapping document is an error), <code>load()</code> / <code>load_with(env)</code>. Same <code>load_with</code> env-injection seam as <code>FileSource</code> for tests. See <a href="/scarab/how-to/layered-config.html">how-to: layered config</a> for the merge semantics and a worked example.</p><h2 id="merge-helpers" tabindex="-1">Merge helpers <a class="header-anchor" href="#merge-helpers" aria-label="Permalink to &quot;Merge helpers&quot;">​</a></h2><p>Pure functions in <code>scarab-config</code> — the half of layered loading that never touches the filesystem:</p><ul><li><code>merge_value(base, overlay)</code> — recursive JSON merge: objects merge key-wise (overlay wins per key, recursing into shared objects); scalars, arrays, and null <strong>replace</strong> — arrays never concatenate</li><li><code>apply_overrides(base, overrides)</code> — flat dotted-path keys (<code>&quot;server.port&quot; → 8080</code>) set leaves, creating intermediate objects; a scalar sitting where a path needs to descend is replaced by an object. Call after the file layers are merged</li><li><code>env_overrides(env, prefix)</code> — <code>&lt;PREFIX&gt;_*</code> env vars → flat dotted keys: the suffix lowercases (<code>__</code> separates path segments), values parse as JSON when possible else stay strings. The bare <code>&lt;PREFIX&gt;</code> var itself is not an override. Feed the result to <code>apply_overrides</code> as the highest-precedence layer — the generic env-overlay half config ports compose on top of file discovery</li></ul><h2 id="resolution-order" tabindex="-1">Resolution order <a class="header-anchor" href="#resolution-order" aria-label="Permalink to &quot;Resolution order&quot;">​</a></h2><p><code>locate</code> picks the config path:</p><ol><li><code>explicit</code> path, else <code>$&lt;NAME&gt;_CONFIG</code> — a named path that doesn&#39;t exist is an error (<code>config file not found: …</code>), not a silent skip</li><li><code>&lt;dir&gt;/&lt;name&gt;.&lt;ext&gt;</code> per search dir, in dir order; within a dir, formats in preference order and each format&#39;s extensions in declared order — YAML before TOML by convention</li></ol><p><code>load</code> reads the file and dispatches parsing by extension; an extensionless explicit path parses with the first (preferred) format; an unclaimed extension errors with <code>no config format claims &#39;.&lt;ext&gt;&#39;</code>.</p><p>When nothing is found, the error names the app, the claimed extensions, and the search steps actually configured.</p><h2 id="path-helpers" tabindex="-1">Path helpers <a class="header-anchor" href="#path-helpers" aria-label="Permalink to &quot;Path helpers&quot;">​</a></h2><ul><li><code>home_dir()</code> — <code>$HOME</code>, else <code>$USERPROFILE</code>, else <code>/</code></li><li><code>expand_tilde(path)</code> — <code>~</code>/<code>~/…</code> expansion; <code>~user</code>, relative, and absolute paths pass through untouched</li><li><code>user_config_dir(name)</code> — <code>~/.config/&lt;name&gt;</code> (tilde expanded at search time)</li></ul>',37)])])}const g=t(o,[["render",d]]);export{k as __pageData,g as default};
